INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter34-movement-state-formation', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p1", "partName": "Formation and Rise of the Telangana Rashtra Samithi", "bodyMd": "The separate-statehood demand, dormant for decades, resurfaced when the UPA coalition at the Centre decided to form three new states in the country. **Kalvakuntla Chandrashekar Rao (KCR)** resigned from the post of Deputy Speaker of the Assembly and from the primary membership of the Telugu Desam Party, and founded the **Telangana Rashtra Samithi (TRS)**.\n\nHe argued that, for decades in \"Vishalandhra,\" Telangana had been kept deliberately undeveloped. The settled Andhra population in the region, he said, had no genuine sympathy for Telangana — those who came to the region were interested only in electoral alliances, not in the region''s welfare.\n\nWith the formation of TRS, the separate-Telangana demand became a central plank in the region''s politics. However, realising he lacked the strength to achieve the goal alone, KCR allied with the Congress ahead of the 2004 elections; the CPI too was a willing supporter of a separate Telangana.\n\n### 2004 Elections and the Congress Alliance\n\n- **2004 Lok Sabha and Assembly elections:** TRS won **5 Lok Sabha seats** and **26 Assembly seats**, becoming part of Congress-led governments both at Delhi and in Hyderabad.\n- KCR and his senior colleague **A. Narendra** took up posts at the Centre; KCR''s nephew **T. Harish Rao**, along with six others, became members of Y.S. Rajasekhara Reddy''s state cabinet.\n- Of the 52 seats Congress contested in the Telangana region in the 2004 Assembly elections, it won 48; TRS won only 26. The Telugu Desam Party won only 11 seats in the region and secured just one Lok Sabha seat.\n\nCongress calculated that an alliance with TRS would prevent Chandrababu Naidu from returning to power a third time under a new political banner, so it extended support to the separate-Telangana sentiment mainly as an anti-TDP strategy, not purely on the merits of the demand.\n\n### Karimnagar By-election and TRS''s Standing\n\nState Sports Minister M. Satyanarayana Rao''s resignation triggered a Karimnagar Lok Sabha by-election.\n\n- Satyanarayana Rao had earlier won from Karimnagar with a majority of **1,56,328 votes** — the biggest record until then.\n- KCR won the by-election with a majority of **2,01,582 votes**, a spectacular victory.\n- This was the first time a regional party (TRS) had taken on the major state parties directly in a big electoral contest, proving that a regional outfit could stand on its own.\n- BJP had promised to introduce a bill in Parliament for separate statehood, but its candidate **C.H. Vidyasagar Rao** lost his deposit in humiliating fashion and blamed TRS for splitting his vote.\n\n### Resignations and the 2008 By-elections\n\nWhen the central coalition government failed to move on Telangana statehood, TRS members resigned in protest from **18 Assembly seats** and **4 Lok Sabha seats** in the state. In the by-elections held in **May 2008**, TRS won back most of the seats it had vacated, delivering unexpected and striking results at a critical juncture of the movement — KCR himself won with a majority of **15,765 votes**.\n\n- Alarmed by these results, Congress worked to dilute the Telangana sentiment and prevent its high command from being swayed.\n- In Nizamabad district, Congress managed to wrest two seats that had been firmly with TRS.\n- Distressed by this partial setback, KCR briefly resigned from the party presidency but was persuaded by senior leaders and workers to withdraw the resignation.\n- Despite the mixed by-election outcome, TRS drew national attention and managed to check defections of its leaders to Congress.\n\n### The 2009 Fast and Its Aftermath\n\nAfter suffering heavy political losses in the **2009 general elections**, KCR remained silent for a period while working internally to keep the movement alive. On **29 November 2009**, he began an **11-day fast** demanding Telangana statehood. Through this fast he drew distant Telangana supporters and movement organisations closer to him and built renewed pressure on the Centre.\n\nIn the by-elections for 8 seats held in **March 2012**, TRS won four of the five seats it contested in Telangana, including Adilabad, Kollapur, and Kamareddy — constituencies where TDP and Congress had traditionally prevailed and where TRS won for the first time. Over its first twelve years, TRS — built and steered single-handedly by KCR, founded in 2001 — overcame repeated setbacks through his political strategy, resilience after election losses, and his ability to connect with Telangana''s public through a native idiom of speech.\n\n---", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p2", "partName": "Political Instability After Y.S. Rajasekhara Reddy (2009–2014)", "bodyMd": "### Y.S. Rajasekhara Reddy''s Second Term\n\n| Party | Seats (2004 Assembly) |\n|---|---|\n| Congress | 183 |\n| CPI | 9 |\n| CPM | 6 |\n| TRS | 26 |\n| TDP | 48 |\n| BJP | 2 |\n| Others | 20 |\n\n**Dr. Y.S. Rajasekhara Reddy (Y.S.R.)** became Chief Minister after this verdict.\n\nAhead of the 2009 elections, TDP chief and then-CM Chandrababu Naidu tried to consolidate coastal-district votes behind a \"Samaikyandhra\" (united Andhra Pradesh) plank, dissolving the Assembly in **November 2003** for snap elections — a gamble that ended with TDP relegated to the bottom of the contest.\n\nY.S.R.''s hold on the Chief Minister''s post was not simply handed down by the high command; it rested on genuine, overwhelming public support. He faced no real internal dissent and no threat of removal by the party leadership, and his government''s achievements were widely seen as his own rather than the party''s.\n\nAhead of the **2009 elections**, Chandrababu Naidu left no opportunity unexplored — including an unprecedented alliance with TRS, despite being long-standing political rivals of KCR — and even reversed the TDP''s stance to declare no objection to a separate Telangana. In this contest TRS won **10 seats**, and Congress returned to power.\n\n**Y.S.R.''s death:** After being re-elected, Rajasekhara Reddy did not remain in power for long — he died in a helicopter crash in the Nallamala forest area on **2 September 2009** while on tour.\n\n### K. Rosaiah''s Tenure\n\nAfter Y.S.R.''s death, Sonia Gandhi appointed the veteran **K. Rosaiah** as Chief Minister, expecting his experience to help navigate the state''s politically sensitive issues. The process of the Congress legislature party electing him was delayed by about three months.\n\nRosaiah — who had earlier won an MLC seat unexpectedly just before the elections — took charge just as the Telangana controversy flared up again, costing him his composure from the outset.\n\n- It would be inaccurate to say Rosaiah \"adjusted\" to the crisis; he largely endured it, often deflecting with remarks such as \"What is in my hands?\" or \"I am just an instrument.\"\n- From the moment **Y.S. Jaganmohan Reddy** (Y.S.R.''s son) took his oath as MLA, demands that he be made Chief Minister created difficulties for Rosaiah, with many ministers and MLAs openly campaigning for Jagan instead of supporting the government.\n- **KCR''s arrest:** As KCR left Karimnagar for Warangal to begin a fast-unto-death, he was intercepted near the Karimnagar district border and taken into custody before he could even begin the fast — an event described as possibly the first of its kind in recent history, where a person was forcibly arrested and jailed before starting an announced fast. His arrest triggered intense unrest across Hyderabad and other parts of Telangana.\n- KCR''s fast-unto-death shook the region; regardless of appeals, he refused to end it. The escalating situation forced the Congress high command to summon Rosaiah to Delhi. KCR ended the fast once the high command agreed to take a decision on Telangana, bringing Rosaiah temporary relief.\n- The subsequent launch of the **Samaikyandhra (united Andhra) movement** created a fresh crisis: MLAs and local-body representatives from Andhra and Rayalaseema began resigning in protest against separating Telangana, turning governance into a largely symbolic exercise.\n- With ministers and legislators divided along regional lines, any decision favouring one side angered the other, leaving Rosaiah unable to focus on governance.\n- Rosaiah''s roughly **14-month tenure** (14 months, 22 days) is remembered as a period defined by external crises rather than his own conduct — a contrast to his earlier, smoother tenure as Finance Minister. After stepping down as CM, he was appointed Governor, a post often regarded as a dignified retirement stage in political life; he has since lived in Chennai away from controversy.\n\nUnion Home Minister P. Chidambaram''s announcement on the night of **9 December 2009** that the process of forming a separate Telangana state would begin immediately jolted the Congress party in Andhra Pradesh, prompting the party to try to walk back the commitment.\n\n### Congress in Decline: N. Kiran Kumar Reddy''s Tenure\n\n**N. Kiran Kumar Reddy** took oath as the **16th Chief Minister of Andhra Pradesh** on **24 November 2010**. Revenue Minister **Botsa Satyanarayana** was made PCC president.\n\nWith the Chief Minister, Assembly Speaker, Legislative Council Chairman, and the new PCC president all drawn largely from Rayalaseema, the high command''s underlying strategy for these key appointments was unclear. Following Y.S.R.''s untimely death — after he had twice built Congress''s electoral fortunes, in 2004 and 2009 — his son Jaganmohan Reddy launched the YSR Congress Party.\n\n- The high command hoped that a young Kiran Kumar Reddy as CM would stabilise the party''s position, but within a short time concluded that his performance fell short of expectations, and dissatisfaction grew within the leadership.\n- To salvage the party''s image, PCC responsibilities were handed to Botsa Satyanarayana, who nonetheless considered himself still in contention for the CM''s post — sparking a rift between the two that the high command could never fully resolve.\n- Kiran Kumar Reddy could not build a loyal faction within the party; even senior cabinet colleagues who supported him did not enjoy his full trust, and key party leaders were largely opposed to him. He had to simultaneously manage the highly sensitive Telangana issue — opposed even within his own party — and the challenge posed by Jagan''s rise.\n- Despite widespread doubts about his position, Kiran Kumar Reddy showed striking self-confidence, believing no danger could touch his post. Within Congress''s political culture, a leader''s survival as CM depended more on the high command''s backing in Delhi than on MLA numbers — the high command traditionally favoured weaker leaders precisely because a leader who built independent strength within the party could become a leader the high command itself might fear crossing.\n- After resigning as CM, Kiran Kumar Reddy raised the \"Jai Samaikyandhra\" banner, but this found no support within Congress itself — having held every post the party could offer, the public was unwilling to forgive him for now condemning it. He remained the **last Chief Minister of undivided Andhra Pradesh**; three months after President''s Rule was imposed, the state was formally divided into Andhra Pradesh and Telangana.\n\n---", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p3", "partName": "Formation of the New Telangana State (2014)", "bodyMd": "### Telangana''s Resources and Potential\n\nAmong India''s larger states, Telangana is not small — in geographical extent it exceeds states such as West Bengal and Kerala. With rich culture, natural resources, and river waters, the region is positioned for further growth.\n\nGiven its hardworking population alongside abundant natural resources — **water, land, and minerals** — planned development could make Telangana the country''s leading state: its river waters can supply irrigation and drinking water, while mineral deposits offer power-generation opportunities unmatched by other southern states.\n\n- The **Krishna** and **Godavari** rivers flow roughly parallel, west to east, across the state, carrying abundant flow for about six months of the year.\n- Other rivers include the **Tungabhadra, Manjeera, Praanahita, Sabari, Suddavagu, Peddavagu (Penganga)**, and **Paleru**.\n- Except for Hyderabad, in the remaining nine districts of Telangana about **90 percent** of the land is cultivable.\n\nTelangana''s freedom struggle was also marked by a flourishing poetic tradition — poetry recitations at library anniversaries, school functions, festivals, and political gatherings — with the region''s first Central Sahitya Akademi award in Telugu going to **Suravaram Pratapareddy**.\n\n### The TRS Victory and Formation of the Government\n\nHaving begun as a movement party under KCR''s leadership on the platform of separate statehood, TRS achieved its stated goal — not merely fulfilling a long-cherished popular aspiration, but also rising to the level of holding state power. Alongside the core Telangana sentiment, the party''s campaign on welfare programmes and development schemes helped it draw voters, while KCR skilfully channelled the region''s sense of neglect and its people''s emotional investment in statehood into a successful movement.\n\nThe Telangana Assembly and Lok Sabha elections were held together on **30 April 2014**, recording **78% statewide polling** — the highest in Nizamabad district and the lowest in Hyderabad. Telangana''s voters gave TRS an overwhelming majority.\n\n**2014 Election Results (Telangana region):**\n\n| Party | Assembly (MLA) Seats | Lok Sabha (MP) Seats |\n|---|---|---|\n| TRS | 63 | 11 |\n| Congress | 21 | 2 |\n| TDP | 15 | 1 |\n| MIM | 7 | 1 |\n| BJP | 5 | 1 |\n| YSR Congress | 3 | 1 |\n| Others | 5 | 0 |\n| **Total** | **119** | **17** |\n\nOn **17 May 2014**, KCR was elected leader of the TRS legislature party. On the morning of **2 June 2014**, Chief Justice **Kalyan Jyoti Sengupta** administered the oath of office to **E.S.L. Narsimhan** as Telangana''s first Governor; Narsimhan then administered the oath to party chief **K. Chandrashekar Rao** as the new state''s **first Chief Minister**, along with 11 other ministers.\n\n### First Cabinet of Telangana\n\n| Minister | Portfolio(s) |\n|---|---|\n| Kalvakuntla Chandrashekar Rao (Chief Minister) | General Administration, Electricity, Municipal Administration, Urban Development, SC, ST, BC and Minority Welfare, and other departments not allotted to other ministers |\n| M.D. Mahmood Ali (Deputy CM) | Revenue, Stamps, Registrations |\n| Dr. Thatikonda Rajaiah (Deputy CM) | Medical and Health |\n| Nayini Narsimha Reddy | Home, Jails, Fire Services, Ex-servicemen Welfare, Lab' WHERE chapter_slug = 'telangana-history-en-chapter34-movement-state-formation';
UPDATE theory_content SET concepts_json = concepts_json || 'our, Employment |\n| Etela Rajender | Finance, Planning, Small Savings Promotion, Civil Supplies |\n| Pocharam Srinivas Reddy | Agriculture and allied departments |\n| Thanneeru Harish Rao | Major Irrigation, Legislative Affairs, Marketing |\n| Kalvakuntla Taraka Rama Rao | Panchayati Raj, Information Technology |\n| P. Mahender Reddy | Transport |\n| Jogu Ramanna | Forests, Environment |\n| T. Jagadish Reddy | Education |\n| T. Padma Rao | Excise, Prohibition |\n\n### Cabinet After Reorganisation\n\n| Minister | Portfolio(s) |\n|---|---|\n| Kalvakuntla Chandrashekar Rao (Chief Minister) | SC and Minority Welfare, Municipal Administration, Urban Development, Electricity, General Administration, and other unallotted departments |\n| Mahmood Ali (Deputy CM) | Revenue, Rehabilitation, Urban Land Ceiling, Stamps and Registration |\n| Kadiyam Srihari (Deputy CM) | Education |\n| T. Harish Rao | Irrigation, Mines, Groundwater, Marketing, Legislative Affairs |\n| Kalvakuntla Taraka Rama Rao | Panchayati Raj, Information Technology, NRI Affairs, Employment |\n| Jupally Krishna Rao | Handlooms and Textiles, Sericulture, Sugar |\n| Nayini Narsimha Reddy | Home, Jails, Fire Services, Ex-servicemen Welfare, Labour, Employment |\n| P. Mahender Reddy | Transport |\n| Pocharam Srinivas Reddy | Agriculture, Horticulture, Sericulture, Animal Husbandry, Fisheries, Food Processing Industries Development Corporation, Seeds Corporation |\n| G. Jagadish Reddy | Electricity/Power |\n| Dr. C. Laxma Reddy | Medical and Health |\n| A. Indrakaran Reddy | Housing, Judiciary, Endowments |\n| Etela Rajender | Small Savings, State Lotteries, Excise Transactions, Legal Metrology, Finance |\n| Jogu Ramanna | Forests, Environment, BC Welfare |\n| T. Padma Rao | Excise, Prohibition, Sports, Youth Welfare |\n| Thummala Nageswara Rao | Roads, Transport, Women and Child Welfare |\n| Talasani Srinivas Yadav | Commercial Taxes, Cinematography |\n| Ajmeera Chandulal | Tribal Welfare, Tourism, Cultural Affairs |\n\nA cabinet extension on **16 December 2014** brought in six new ministers, including A. Indrakaran Reddy, C. Laxma Reddy, Talasani Srinivas Yadav, Thummala Nageswara Rao, Jupally Krishna Rao, and Ajmeera Chandulal — the appointments reflected in the reorganised cabinet table above. On **25 January 2017**, **Dr. Thatikonda Rajaiah** was removed as Deputy Chief Minister over corruption allegations; **Kadiyam Srihari** was appointed Deputy CM and Education Minister in his place, **G. Jagadish Reddy** was shifted from Education to Electricity, and **C. Laxma Reddy** was given the Medical and Health portfolio.\n\n---", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p4", "partName": "Intensification of the Movement: TJAC and Forms of Protest", "bodyMd": "Following the Centre''s announcement on **9 December 2009** that the process of Telangana formation would begin, Seemandhra political leaders resigned en masse in protest, creating political and constitutional turmoil. Under this pressure, the Centre issued a second statement on **23 December 2009**, saying state formation would proceed \"only after consultations and consensus.\"\n\nTo transform the Telangana aspiration into a mass movement and unite the community''s various public unions and political parties, the **Telangana Political Joint Action Committee (TJAC)** was formed on **24 December 2009**.\n\nTJAC organised a wide range of protest programmes to sustain pressure on the Centre and keep the movement''s aspirations alive: the non-cooperation movement, the million march, Sakala Janula Samme, Sagaraharam, Samsad Yatra, and Chalo Assembly. Alongside these, the region''s cultural life — Bathukamma, Bonalu processions, and folk performance — was woven into peaceful protest through forms such as rasta roko (road blockades), hunger strikes, vanta-varpu (community cooking on roads), dhoom-dham (song-and-dance protest), manavaharam (human chains), funeral processions, candle rallies, and effigy burning.\n\n### Non-Cooperation Movement (17 February – 4 March 2011)\n\nThe non-cooperation movement — inspired by Gandhi''s non-cooperation movement against British rule — aimed to make the government helpless by having employees withhold cooperation and duties. It was TJAC''s **first major agitation programme**, demanding immediate introduction of a Telangana bill in Parliament, and lasted **16 days**.\n\n**Lead-up events:**\n\n| Date (Feb 2011) | Event |\n|---|---|\n| 13th | Dappu Chatimpu and tying of Kankanalu (yellow threads) |\n| 14th | Rallies held in constituencies |\n| 15th | \"Jail Bharo\" programme |\n| 16th | Dharna at houses of Congress and TDP MPs/MLAs |\n| 17th | Movement launched; ~3 lakh employees joined; Telangana MLAs disrupted the Governor''s Assembly address |\n\nThrough the following days, employees boycotted duty, withheld taxes, travelled without tickets, blockaded national highways, and held rallies. Key events included picketing of Central government offices (18th), \"Walk for Telangana\" and \"Prabathabheri\" protests with a blockade of NH-9 (19th), and \"Chalo Assembly\" and \"Chalo Raj Bhavan\" calls by student and lawyer JACs (21st).\n\nA 48-hour bandh followed across ten Telangana districts (22nd), Lok Sabha members chanted \"Jai Telangana\" and the House was adjourned three times (23rd), and a \"Rail Roko\" titled \"Palle Palle Pattala Paiki\" blocked North–South rail traffic (1 March). The movement ended on **4 March 2011** after TJAC and trade union leaders reached an agreement with state ministers.\n\n**Key points of the 4 March 2011 agreement:**\n1. A commission headed by a retired judge to oversee implementation of Presidential orders.\n2. The state government to take JAC leaders to Delhi to press for removal of paragraph 14(F) of the Presidential orders.\n3. A monitoring committee for implementation of Presidential orders, chaired by the Council of Ministers.\n4. A policy to ensure adequate representation for Telangana-district employees in state-level offices.\n5. Preference to local candidates in pending recruitments.\n\n### Million March (10 March 2011)\n\nThe Million March, held at Tank Bund, Hyderabad, was inspired by the Tahrir Square protests in Cairo, though condensed into a single day.\n\n- On **26 February 2011**, KCR — as chief guest at an employees'' hunger strike near the Inter Educational Directorate, Nampally — announced the million march without first consulting TJAC; public unions and the JAC nonetheless extended support.\n- Police denied permission and imposed **Section 144** in Hyderabad; JAC convenor **Prof. Kodandaram** and **Nayini Narsimha Reddy**, along with over a thousand activists, were arrested in advance to disrupt the programme.\n- Despite barricades and heavy policing, large numbers reached Tank Bund; Congress MP **Madhu Yashki Goud** and senior leader **K. Keshava Rao** were attacked by the crowd for not having resigned their posts.\n\n**Destruction of statues at Tank Bund:**\n- In 1986, then-CM **N.T. Rama Rao** had installed 33 statues of eminent Telugu personalities on Tank Bund; only 7 represented Telangana — Rudrama Devi, Pothana, Abul Hasan Tanisha, Ramadasu (Kancharla Gopanna), Mahbub Ali Khan, Makhdoom Mohiuddin, and Suravaram Pratap Reddy (an 8th, Komaram Bheem, was added later on **5 October 2012**).\n- When police did not respond to demands for the release of arrested activists, outraged protestors destroyed **16 statues** of predominantly Andhra figures, believing Telangana''s own history had been sidelined; some statues were thrown into Hussain Sagar, and 15 media personnel covering the incident were injured.\n- KCR, Prof. Kodandaram, Harish Rao, and KTR were among those booked under serious sections, including attempt to murder.\n- A cabinet sub-committee headed by **Vatti Vasanth Kumar** was formed to decide on re-installing the destroyed statues, but Telangana cultural organisations warned against installing any new statue on Tank Bund until statehood was achieved.\n\n### Sakala Janula Samme (13 September – 24 October 2011)\n\nSakala Janula Samme (\"strike of all the people\") was the movement''s most comprehensive mobilisation, spanning **42 days** and drawing in teachers, students, and public and private trade unions across Telangana.\n\n- On **15 July 2011**, TJAC-led trade unions issued a strike notice to CM Kiran Kumar Reddy, warning of a strike if statehood was not achieved by 1 August 2011; the government did not respond.\n- The strike, originally planned from 6 September, was postponed to **13 September** on account of Ganesh festival; a **Janagarjana Sabha** at Karimnagar on 12 September drew roughly 10 lakh people and confirmed the strike date. **Singareni coal workers** began the strike from midnight of 12/13 September.\n- The government invoked **G.O. No. 177** (salary deduction for absent employees) and threatened \"No Work – No Pay\"; KCR promised employees back pay with interest, plus a month''s bonus, once statehood was achieved.\n- The strike revealed that **80% of secretariat employees** were from the Seemandhra region, reinforcing Telangana''s sense of exclusion from job appointments.\n- **RTC workers** (about 67,000) joined from 19 September, blocking national highways; clashes with police at Nizam College and Osmania University left students **Kishore Goud** and **Shiva Goud** wounded by rubber bullets.\n- On **1 October 2011**, Congress MLA and Minister **Komati Reddy Venkat Reddy** resigned in protest; he began a fast-unto-death on 1 November 2011 (withdrawn on 9 November after police intervention).\n- Strikes wound down in stages through October: RTC workers ended their 27-day strike (16th), the Teachers'' Action Committee called off its strike (17th), Singareni workers ended their 35-day strike (18th), and finally **TNGO** called off the strike on **24 October 2011**, ending Sakala Janula Samme.\n\n**Key points of the agreement ending the strike:**\n1. Reaffirmed the 4 March 2011 commitment on a retired-judge commission for Presidential order implementation.\n2. Withdrawal of criminal cases against employees without direct involvement.\n3. Government to consult the Advocate General on cancelling G.O. No. 177.\n4. Sympathetic review of deputations and transfers made during the strike.\n5. Review of ESMA notifications issued during the strike in certain departments.\n6. Consideration of treating the strike period as paid or other leave.\n7. Re-hiring of outstanding contract employees.\n8. A special advance to be paid to employees despite \"No Work – No Pay,\" in view of festival-season hardship.\n\n### Sagaraharam / Telangana March (30 September 2012)\n\nAnnounced by JAC chairman Prof. Kodandaram on 7 July 2012 as \"Chalo Hyderabad\" under the slogan \"Intiko Manishi, Chethilo Janda,\" the march was renamed **Sagaraharam** on the suggestion of Mallepalli Laxmaiah. The government initially refused permission, citing potential damage to state assets and clashing events (Ganesh immersion, a UN biodiversity conference), before permitting the march from Sanjeevaiah Park to Necklace Road, 3 pm–7 pm.\n\nOn the day, all trains through the region were cancelled and Osmania University was sealed, yet nearly **2 lakh activists** reached Necklace Road. The crowd stayed past the government deadline, leading police to use tear gas, before the march was called off around 11:30 pm due to rain.\n\n### Chalo Assembly (14 June 2013) and Samsad Yatra – Chalo Delhi (April 2013)\n\n- For **Samsad Yatra**, nearly 2,000 activists travelled to Delhi by a special train named \"Telangana Express\" (27 April 2013); a **Satyagraha Deeksha** began at Jantar Mantar on 29 April 2013, drawing support from national leaders including CPI''s Suravaram Sudhakar Reddy and BJP''s Prakash Javadekar, Sushma Swaraj, Uma Bharati, and Smriti Irani. Telangana Congress MPs staged a 48-hour sit-in near the Mahatma Gandhi statue in Parliament.\n- For **Chalo Assembly** (14 June 2013), the government denied permission and pre-emptively arrested activists and raided university hostels; the Assembly session was cancelled that day, but thousands of activists still gathered, and TRS MLAs **Dasyam Vinay Bhaskar** and **Vidya Sagar Rao** climbed onto the Assembly building to protest with black flags.\n\n### Other Forms of Protest\n\n- **Vanta-Varpu** (\"community cooking\"): first held on **3 February 2010** (the day the Sri Krishna Committee was appointed), with community cooking blocking the Hyderabad–Karimnagar and Hyderabad–Warangal roads; repeated on 19 June 2011 as \"Rajadhanilo Vanta, Delhilo Manta\" across 150 centres in Hyderabad.\n- **Manavaharam (Human Chain):** on **4 February 2010**, a human chain of **500 kilometres** across six districts (Adilabad to Alampur, via Mahbubnagar, Nizamabad, Medak, Ranga Reddy, Hyderabad) was formed — the longest human chain in the country''s history; a second chain followed on 5 February 2010 along NH-9 between Hyderabad and Kodad.\n- **TJAC Bus Yatra:** conducted in two phases — Gun Park (Hyderabad) to Hanumakonda (21–23 March 2010) and Komuravelli to Mancherial (9–12 April 2010).\n- **Palle Palle Pattala Paiki** (\"villages onto the railway tracks\"): a Rail Roko programme on 1 March 2011.\n- **TJAC Singareni Yatra** (9 November 2011): three teams under Prof. Kodandaram, Mallepalli Lakshmaiah, and Pittala Ravinder covered the Khammam, Karimnagar, and Adilabad coal-belt areas; the first two teams were arrested en route, while Pittala Ravinder''s team reached Kothagudem.\n- **Samara Deeksha** (27–28 January 2013): a 36-hour protest at Indira Park, where Prof. Kodandaram gave the slogan \"Congress ko Khatam Karo – Telangana Hasil Karo.\"\n- **Sadak Bandh** (21 March 2013): a road blockade on NH-44 between Shamshabad and Alampur; non-bailable cases were registered against Prof. Kodandaram and TRS MLAs Etela Rajender and Jupally Krishna Rao.\n\n### Hunger Strikes for Separate Telangana\n\n| Leader | Duration |\n|---|---|\n| Ravindranath | 8–22 January 1969 |\n| Potu Krishnamurthy | 10–23 January 1969 |\n| Konda Laxman | 5–8 April 1969 |\n| Ravindra Babu | 20 July – 1 August 1969 |\n| Mallikarjun | 10 October – 3 November 1969 |\n| Ramadevi | 18–24 October 1969 |\n| Vishnuvardhan, Jaleel | 21–26 October 1969 |\n| Konda Laxman | 1–12 November 1969 |\n| KCR | 29 November – 9 December 2009 |\n| Konda Laxman | 1–7 November 2011 |\n| Komati Reddy Venkat Reddy | 1–9 November 2011 |\n| Nalini (former DSP) | 9–16 December 2011 |\n\n---", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p5", "partName": "Parliamentary Process for the Formation of Telangana State", "bodyMd": "### Article 3 of the Constitution\n\n**Article 3** governs the formation of new states and the alteration of existing state boundaries or names. Under it, Parliament holds absolute power over the formation and modification of states, while ' WHERE chapter_slug = 'telangana-history-en-chapter34-movement-state-formation';
UPDATE theory_content SET concepts_json = concepts_json || 'the affected state legislatures have only an **advisory role**:\n\n- A new state may be formed by separating territory from an existing state, by merging two or more states or territories, or by merging any territory with part of a state.\n- Parliament may increase or decrease a state''s area, alter its boundaries, or alter its name.\n- The Union Cabinet forwards the bill to the President, who sends it to the concerned state legislature for its opinion within a set (extendable) time period — in the Andhra Pradesh case, the deadline was extended.\n- The state legislature may approve or disapprove the bill, but Parliament is **not bound** to accept its views (the Andhra Pradesh legislature in fact rejected the bill, which nonetheless proceeded).\n- A **simple majority** — not a two-thirds special majority — is sufficient to pass a state-partition bill in Parliament, and even the debate quorum requires only 10% of members.\n\n### Key Case Law on State Partition\n\n- **Babulal Parate vs. State of Bombay (1959):** The Supreme Court held that once a draft bill has been sent to the state legislature and its views received, the Centre may make key changes before introducing the bill in Parliament without needing to again consult the legislature; Parliament is not bound by the state legislature''s views. The Court held that sovereignty rests with the people of India, constituted by the union of states.\n- **Mangal Singh vs. Union of India (1987):** Parliament has the power to create new states or alter existing ones, provided this does not violate the spirit of the Constitution.\n- **Mullaperiyar & Environmental Protection Forum vs. Union of India (2006):** Parliament''s power in matters of state division under Articles 3 and 4 is supreme and absolute.\n- **Pradeep Chaudhary vs. Union of India (2009):** Parliament is not bound to accept the state legislature''s views — \"consultation\" means seeking an opinion, not obtaining assent; Parliament''s supreme authority in this regard cannot be challenged under Article 246 or the Seventh Schedule. This judgment is treated as the standard reference on state-partition procedure, and its reasoning was earlier upheld in the **Berubari case** (via *V.B. Raju vs. State of Gujarat*, 1980).\n\n### The UPA Government''s Shifting Stance\n\nFollowing KCR''s fast-unto-death, Union Home Minister Chidambaram announced on **9 December 2009** that Telangana formation would begin, but Seemandhra resignations forced a reversal on **23 December 2009**. An all-party meeting called by the Home Ministry on **5 January 2010** failed to satisfy any side, intensifying the movement.\n\nThis led the Centre to appoint the **Sri Krishna Committee** on **3 February 2010** \"citing the need for detailed consultation.\" The Committee submitted its report on **30 December 2010**, but the Centre did not act on it for over two years, prompting TJAC''s escalating protest calendar (non-cooperation, million march, Sakala Janula Samme).\n\n**Committees and turning points, 2012–2013:**\n\n- **All-Party Meeting (28 December 2012):** Chaired by Home Minister Sushil Kumar Shinde in Delhi, with two representatives each (one from Telangana, one from Andhra/Rayalaseema) from Congress, TRS, TDP, BJP, YSRCP, CPI, CPM, and MIM; CM Kiran Kumar Reddy attended as special invitee. Shinde promised a solution within a month, though it was delayed — this meeting is regarded as the most significant of all such meetings, since the CWC''s later decision built directly on it.\n- **CWC Resolution (30 July 2013):** After senior Congress leader K. Keshava Rao and two other MPs defected to TRS, and a BJP public meeting in Hyderabad (3 June 2013) signalled political shifts, the Congress Working Committee met under Sonia Gandhi, PM Manmohan Singh, and other senior leaders. It decided to form Telangana with **10 districts including Hyderabad**, with Hyderabad as joint capital for 10 years, national status for the Polavaram project, and a new Andhra Pradesh capital to be built within a decade.\n- **Antony Committee (6 August 2013):** Formed under **A.K. Antony** (with Digvijay Singh, Veerappa Moily, and Ahmed Patel) to coordinate the partition process; also called the \"Partition Committee.\" Its report (4 October 2013) recommended **GHMC** (rather than the wider HMDA) as the joint-capital boundary, equal educational opportunities for Seemandhra students in Hyderabad for 10 years, and national-project status with rehabilitation measures for Polavaram.\n- **Group of Ministers – GoM (8 October 2013):** Chaired by A.K. Antony, with Sushil Kumar Shinde, Chidambaram, Veerappa Moily, Jairam Ramesh, and Ghulam Nabi Azad as members, given six weeks to resolve post-partition issues. Party positions before the GoM diverged sharply. **TRS** wanted no administrative control over Telangana and joint-capital status limited to five years; **TDP** boycotted the process, calling it unilateral. **AIMIM** opposed any Central rule over Hyderabad and sought an anti-communal-violence bill; **YSRCP** favoured a united Andhra Pradesh. **CPM** favoured continued linguistic-state unity, while **BJP** sought a national-parties meeting before Parliament approval. A demand for a separate **\"Rayala Telangana\"** by Rayalaseema leaders J.C. Divakar Reddy and T.G. Venkatesh was ultimately dropped after TRS-led protests (4–5 December 2013).\n\n### Passage of the Andhra Pradesh Reorganisation Bill\n\n| Date | Event |\n|---|---|\n| 5 December 2013 | GoM finalised its report; Union Cabinet approved the Telangana Draft Bill 2013 |\n| 11 December 2013 | President Pranab Mukherjee sent the bill to the State Assembly, allowing 45 days (later extended by a week) for its opinion |\n| 16 December 2013 | Bill introduced in the Assembly and Legislative Council by Speaker Nadendla Manohar; Seemandhra MLAs tore up copies in protest |\n| 30 January 2014 | Assembly passed a Rule 77 resolution asking the President not to introduce the bill; the bill was returned to the Centre as rejected (9,072 amendments had been proposed; 87 members spoke) |\n| 7 February 2014 | Union Cabinet approved the bill despite the Assembly''s rejection (Parliament not bound to comply, per the Home Ministry) |\n| 13 February 2014 | \"Andhra Pradesh Reorganisation Bill, 2013\" introduced in the Lok Sabha by Sushil Kumar Shinde; MP Lagadapati Rajgopal used pepper spray during the debate, causing the House to adjourn; 16 MPs (14 Seemandhra, 2 Telangana) were suspended |\n| 18 February 2014 | Lok Sabha passed the bill by voice vote |\n| 19 February 2014 | CM Kiran Kumar Reddy resigned as CM, MLA, and from Congress; bill introduced in the Rajya Sabha |\n| 20 February 2014 | Rajya Sabha passed the bill by voice vote after PM Manmohan Singh offered Andhra Pradesh six guarantees, including special category status for five years and central completion of the Polavaram project |\n| 1 March 2014 | President''s assent given; President''s Rule imposed on united Andhra Pradesh |\n| 2 March 2014 | Bill notified as the **Andhra Pradesh Re-organisation Act, 2014** in the Gazette of India (a 71-page Act) |\n| 4 March 2014 | **2 June 2014** declared as Telangana''s \"Appointed Day\" |\n| 2 June 2014 | Telangana became India''s **29th state** |\n\nSeparately, six Congress MPs from Seemandhra (Lagadapati Rajgopal, Sabbam Hari, Undavalli Arun Kumar, Rayapati Sambasiva Rao, Sai Pratap, and Harsha Kumar) moved a no-confidence motion against the Centre and were suspended from the party on 11 February 2014. On 1 March 2014, before the Act took effect, the Cabinet decided to merge **seven Polavaram-affected mandals** of Khammam district into Andhra Pradesh — an amendment formalised by ordinance and approved by the President on 28 May 2014.\n\nThe government also set up **14 department-wise committees** (covering Finance, Irrigation, Planning, Roads and Buildings, Energy, Industries, Medical and Health, Revenue, and General Administration, among others) on 1 March 2014 to oversee the partition, alongside a high-level committee headed by a Special Chief Secretary and a State Reorganization Cell in the Secretariat.\n\n### The Andhra Pradesh Re-organisation Act, 2014\n\nThe Act comprises **12 parts, 108 sections, and 13 schedules**. Key provisions include:\n\n- **Section 3:** Formed the State of Telangana from ten districts — Adilabad, Nizamabad, Karimnagar, Medak, Warangal, Nalgonda, Ranga Reddy, Hyderabad, Khammam, and Mahbubnagar (later modified by the Polavaram-related ordinance transferring parts of Khammam to Andhra Pradesh).\n- **Section 5:** Made Hyderabad the **common capital** of both states for a period not exceeding 10 years.\n- **Section 6:** Provided for an expert committee to recommend a new capital for Andhra Pradesh within six months.\n- **Sections 7–9:** The existing Governor to serve both states; the Governor responsible for security of life and property in the common capital, assisted by two Central-government-appointed advisors; Central assistance for additional police forces.\n- **Section 12–14:** Allocated **7 Rajya Sabha seats to Telangana and 11 to Andhra Pradesh**; allocated **17 Lok Sabha seats** to Telangana.\n- **Section 17:** Fixed Assembly strength at **119 seats for Telangana and 175 for Andhra Pradesh** (later increased under Section 26 to 153 and 225 respectively, subject to delimitation).\n- **Section 18:** Provided for one nominated Anglo-Indian member each in both Assemblies.\n- **Section 22:** Provided Legislative Councils of up to 40 members (Telangana) and 50 members (Andhra Pradesh).\n- **Section 30–33:** The Hyderabad High Court to remain the common High Court until a separate Andhra Pradesh High Court is constituted.\n- **Section 46–67:** Governed distribution of revenue, assets, liabilities, debts, pensions, and provident funds between the successor states, generally on a population-ratio basis.\n- **Section 84:** Provided for a **Godavari River Management Board** (Telangana) and a **Krishna River Management Board** (Andhra Pradesh), supervised by a Central **Apex Council** chaired by the Union Water Resources Minister.\n- **Section 90:** Declared the **Polavaram Irrigation Project** a national project, with the Centre responsible for construction.\n- **Section 95:** Continued the Article 371D local-quota protections for higher education in both states for **10 years**.\n- **Schedule 13:** Listed Central development measures for 10 years, including a tribal university and a horticultural university in Telangana, a 4,000 MW NTPC power facility, and a rail coach factory.\n\n---", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter34-movement-state-formation-p6", "partName": "Notable \"Firsts\" of Telangana State", "bodyMd": "| Position | First Holder |\n|---|---|\n| Chief Minister | Kalvakuntla Chandrashekar Rao |\n| Governor | E.S.L. Narsimhan |\n| Speaker, Legislative Assembly | E. Madhusudhana Chary |\n| Deputy Speaker | Padma Devender Reddy |\n| Chairman, Legislative Council | K. Swamy Goud |\n| Deputy Chairman, Legislative Council | Nethi Vidya Sagar |\n| Leader of Opposition, Assembly | K. Jana Reddy (Congress) |\n| Pro-tem Speaker | K. Jana Reddy (Congress) |\n| Anglo-Indian nominated MLA | Stephenson |\n| Leader of Opposition, Legislative Council | D. Srinivas |\n| Advocate General | K. Rama Krishna Reddy |\n| Chief Secretary | Rajeev Sharma |\n| Director General of Police | Anurag Sharma |\n| Chief Information Commissioner | Prabhakar Reddy |\n| Chief Justice, High Court | T.B. Radhakrishnan |\n| Chairman, Public Service Commission | Ganta Chakrapani |\n| Chairman, Women''s Commission | Sunitha Lakshma Reddy |\n| Chairman, SC/ST Commission | Errolla Srinivas |\n| Chairman, Minority Commission | Mohammad Kamruddin |\n| Mayor, GHMC | Bonthu Rammohan |\n| Deputy Mayor, GHMC | Baba Fasiuddin |\n| Ambassador (from Telangana) | Sania Mirza |", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter34-movement-state-formation';
